def link(p='',base=''):
 return base+(p+'.html' if p else 'index.html')
def arrow():return '<span aria-hidden="true">↗</span>'
def button(p,label,base='',dark=False):return f'<a class="button {"button-dark" if dark else ""}" href="{link(p,base)}">{label}{arrow()}</a>'
def picture(name,alt,base='',cls='',eager=False):
 return f'<img class="{cls}" src="{base}assets/{name}" alt="{escape(alt)}" {"fetchpriority=\"high\"" if eager else "loading=\"lazy\""} decoding="async">'
def header(base,current):
 nav=[('leistungen','Leistungen'),('ueber-uns','Über uns'),('stellenangebote','Karriere'),('kontakt','Kontakt')]
