def shell(title,description,content,base='',current=''):
 return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#d5312b"><meta name="robots" content="noindex,nofollow"><title>{escape(title)} | Elektro Freitag</title><meta name="description" content="{escape(description)}"><link rel="icon" href="{base}assets/favicon.svg"><link rel="stylesheet" href="{base}assets/style.css"><script src="{base}assets/main.js" defer></script></head><body>{header(base,current)}<main id="main">{content}</main>{footer(base)}</body></html>'''
def save(path,title,description,fn,current=''):
 p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);base='../'*len(Path(path).parts[:-1]);p.write_text(shell(title,description,fn(base),base,current),encoding='utf-8')
def intro(kicker,title,lead,base='',photo=None,caption=''):
 return f'''<section class="page-intro wrap"><div class="breadcrumb"><a href="{link('',base)}">Startseite</a><span>/</span><span>{kicker}</span></div><div class="intro-grid"><div><p class="eyebrow">{kicker}</p><h1>{title}</h1></div><p class="intro-lead">{lead}</p></div></section>'''+(f'<figure class="page-photo wrap">{picture(photo,caption,base,eager=True)}<figcaption>{caption}</figcaption></figure>' if photo else '')
