def legal(base,privacy=False):
 if privacy:
  title='Datenschutz';content='''<h2>Hinweise zu diesem Website-Entwurf</h2><p>Diese Präsentationsversion dient der Vorstellung eines neuen Website-Auftritts. Sie ist noch nicht der freigegebene offizielle Internetauftritt von Elektro Freitag. Die endgültige Datenschutzerklärung ist vor einem offiziellen Livegang auf Betreiber, Hosting und eingesetzte Dienste abzustimmen.</p><h2>Lokale Inhalte und Funktionen</h2><p>Die Seiten laden Schriften, Bilder, Styles und JavaScript lokal. Im Website-Code sind keine Analysewerkzeuge, Werbetracker, Drittanbieter-Schriften oder eingebetteten Karten integriert. Der Website-Code setzt keine Cookies und nutzt keinen dauerhaften Browser-Speicher.</p><h2>Kontaktaufnahme</h2><p>Das Formular bereitet eine E-Mail vor. Die eingegebenen Daten werden zunächst nur im geöffneten Browser verarbeitet. Erst wenn Sie den erzeugten Link öffnen und die Nachricht in Ihrem E-Mail-Programm senden, übermitteln Sie die Daten über Ihren E-Mail-Anbieter. Alternativ können Sie direkt telefonisch oder per E-Mail Kontakt aufnehmen.</p><h2>Hosting und externe Links</h2><p>Beim Aufruf einer gehosteten Website entstehen technische Verbindungsdaten, beispielsweise IP-Adresse und Zeitpunkt des Abrufs. Die Verarbeitung richtet sich nach dem verwendeten Hosting und dessen Vertragsbedingungen. Externe Angebote wie Google Maps oder das E-Mail-Programm werden erst durch einen aktiven Klick geöffnet.</p><h2>Unternehmensbezogene Fragen</h2><p>Elektro Freitag · Hans Freitag<br>Archshofen 5 · 91555 Feuchtwangen<br>info@elektro-freitag.net</p><h2>Bilder im Entwurf</h2><p>Logo und Fotos des Verkaufsbereichs stammen aus dem bestehenden Unternehmensauftritt. Das Architekturmotiv und das Detailmotiv der Gebäudesteuerung sind erzeugte Illustrationsbilder; sie zeigen keine nachgewiesenen Projekte des Unternehmens.</p>'''
 else:
  title='Impressum';content='''<h2>Unternehmensangaben</h2><p>Hans Freitag<br>Elektro Freitag<br>Archshofen 5<br>91555 Feuchtwangen</p><h2>Kontakt</h2><p>Telefon: 09852 / 2428<br>Telefax: 09852 / 908489<br>E-Mail: info@elektro-freitag.net</p><h2>Umsatzsteuer-ID</h2><p>DE 186320527</p><h2>Präsentationsstand</h2><p>Dies ist ein Website-Entwurf von Kaiser-Webdesign zur Kundenvorstellung. Die Unternehmensangaben wurden dem bestehenden Internetauftritt entnommen und müssen für die offizielle Veröffentlichung bestätigt werden.</p>'''
 original='datenschutz' if privacy else 'impressum'
 return intro(title,title+'.','Informationen zum Unternehmen und zu dieser Präsentationsversion.',base)+f'<section class="section wrap legal-content">{content}<p><a class="text-link" href="https://www.elektro-freitag.net/footer/{original}.html" target="_blank" rel="noopener noreferrer">Angaben auf der bisherigen Website {arrow()}</a></p></section>'
save('footer/impressum.html','Impressum','Unternehmensangaben und Hinweise zum Präsentationsentwurf.',lambda b:legal(b))
save('footer/datenschutz.html','Datenschutz','Datenschutzhinweise zum Präsentationsentwurf.',lambda b:legal(b,True))
save('404.html','Seite nicht gefunden','Die angeforderte Seite ist nicht vorhanden.',lambda b:intro('404','Hier geht es<br>nicht weiter.','Zurück zum passenden Einstieg.',b)+f'<section class="section wrap">{button("","Zur Startseite",b)}</section>')
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(OUT/'.nojekyll').write_text('')
(OUT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="8" fill="#d5312b"/><path d="M19 15h30v8H28v9h17v8H28v13h-9z" fill="white"/></svg>')
print('Built',len(list(OUT.rglob('*.html'))),'pages')
